'use strict';

// MAIN //

var valid = [];
var test;

test = {
	'code': [
		'/**',
		'* Squares a number.',
		'*',
		'* @param {number} x - input number',
		'* @returns {number} x squared',
		'*',
		'* @example',
		'* var y = square( 2.0 );',
		'* // returns 4.0',
		'*/',
		'function square( x ) {',
		'  return x*x;',
		'}'
	].join( '\n' )
};
valid.push( test );

test = {
	'code': [
		'/**',
		'* Returns a pseudo-random number on [0,1].',
		'*',
		'* @param {string} [str="hello - world"] - input string with hyphen in default',
		'* @returns {number} uniform random number',
		'*/',
		'function rand( str ) {',
		'  return Math.random();',
		'}'
	].join( '\n' )
};
valid.push( test );

test = {
	'code': [
		'/**',
		'* Function with no description on param.',
		'*',
		'* @param {number} x',
		'* @returns {number} x',
		'*/',
		'function id( x ) {',
		'  return x;',
		'}'
	].join( '\n' )
};
valid.push( test );

test = {
	'code': [
		'/**',
		'* Squares a number.',
		'*',
		'* @param {number} x - input number',
		'* @returns {number} x squared',
		'*/',
		'function square( x ) {',
		'  return x*x;',
		'}'
	].join( '\n' ),
	'options': [
		{
			'before': true,
			'after': true
		}
	]
};
valid.push( test );

test = {
	'code': [
		'/**',
		'* Squares a number.',
		'*',
		'* @param {number} x-input number',
		'* @returns {number} x squared',
		'*/',
		'function square( x ) {',
		'  return x*x;',
		'}'
	].join( '\n' ),
	'options': [
		{
			'before': false,
			'after': false
		}
	]
};
valid.push( test );


// EXPORTS //

module.exports = valid;
